501	// Project grid renderer
502	// ---------------------------------------------------------------------------
503	
504	/**
505	 * Render a (possibly empty) array of project detail objects into
506	 * `listContainer`.
507	 *
508	 * Shows "No projects match the current filters." when `filtered` is empty but
509	 * `_allProjects` is non-empty (i.e. filters excluded everything).
510	 * Shows the original "No projects yet." message when there are no projects at all.
511	 * Otherwise renders the project cards inside a `.project-grid` wrapper.
512	 *
513	 * @param {HTMLElement}                                  listContainer
514	 * @param {Array<{ fullProject: Object, wsCount: number }>} filtered
515	 */
516	function renderProjectGrid(listContainer, filtered) {
517	    clearElement(listContainer);
518	
519	    if (filtered.length === 0) {
520	        const empty = document.createElement('div');
521	        empty.className = 'empty-state';
522	        if (_allProjects.length === 0) {
523	            empty.textContent = 'No projects yet. Use the "Create Project" button to add one.';
524	        } else {
525	            empty.textContent = 'No projects match the current filters.';
526	        }
527	        listContainer.appendChild(empty);
528	        return;
529	    }
530	
531	    const grid = document.createElement('div');
532	    grid.className = 'project-grid';
533	
534	    filtered.forEach(({ fullProject, wsCount }) => {
535	        grid.appendChild(buildProjectCard(fullProject, wsCount));
536	    });
537	
538	    listContainer.appendChild(grid);
539	}
