541	// ---------------------------------------------------------------------------
542	// Project list — fetch + render
543	// ---------------------------------------------------------------------------
544	
545	/**
546	 * Fetch all project data from the API, update `_allProjects`, then apply
547	 * the current `filterState` and render the result into `listContainer`.
548	 *
549	 * Workspace counts are fetched in parallel for each project.  If a workspace
550	 * fetch fails the count is shown as "0 workspaces" rather than breaking the
551	 * whole list.
552	 *
553	 * @param {HTMLElement} listContainer - Element to render the list into.
554	 * @param {FilterState} filterState   - Current filter/sort state to apply
555	 *   after the data is loaded.
556	 */
557	async function renderProjectList(listContainer, filterState) {
558	    showLoading(listContainer);
559	
560	    let projects;
561	    try {
562	        projects = await api.projects.list();
563	    } catch (err) {
564	        clearElement(listContainer);
565	        const errMsg = document.createElement('div');
566	        errMsg.className = 'empty-state error-state';
567	        errMsg.textContent = `Failed to load projects: ${err.message}`;
568	        listContainer.appendChild(errMsg);
569	        showToast(err.message || 'Failed to load projects.', 'error');
570	        return;
571	    }
572	
573	    if (!Array.isArray(projects) || projects.length === 0) {
574	        _allProjects = [];
575	        renderProjectGrid(listContainer, []);
576	        return;
577	    }
578	
579	    // Fetch full project data + workspace counts in parallel per project.
580	    const projectDetails = await Promise.all(
581	        projects.map(async (project) => {
582	            const id = project.Id || project.id || '';
583	            let fullProject = project;
584	            let wsCount = 0;
585	            try {
586	                const [full, workspaces] = await Promise.all([
587	                    api.projects.get(id),
588	                    api.workspaces.list(id),
589	                ]);
590	                fullProject = full;
591	                wsCount = Array.isArray(workspaces) ? workspaces.length : 0;
592	            } catch (_err) {
593	                // Degrade gracefully — show index data with 0 counts.
594	            }
595	            return { fullProject, wsCount };
596	        }),
597	    );
598	
599	    _allProjects = projectDetails;
600	
601	    const filtered = applyFiltersAndSort(filterState);
602	    renderProjectGrid(listContainer, filtered);
603	}
