606	// Public export — view function
607	// ---------------------------------------------------------------------------
608	
609	/**
610	 * Render the dashboard view.
611	 *
612	 * @param {HTMLElement} container - The `#app` root element.
613	 * @param {Object}      _params   - Route params (unused).
614	 */
615	export async function renderDashboard(container, _params) {
616	    // -----------------------------------------------------------------------
617	    // Page header
618	    // -----------------------------------------------------------------------
619	    const header = document.createElement('div');
620	    header.className = 'page-header';
621	
622	    const title = document.createElement('h1');
623	    title.textContent = 'Projects';
624	    header.appendChild(title);
625	
626	    container.appendChild(header);
627	
628	    // -----------------------------------------------------------------------
629	    // Project list section (declared early so onFilterChange can reference it)
630	    // -----------------------------------------------------------------------
631	    const listContainer = document.createElement('div');
632	    listContainer.className = 'project-list-container';
633	
634	    // -----------------------------------------------------------------------
635	    // Filter / sort toolbar (inserted between header and project list)
636	    // -----------------------------------------------------------------------
637	
638	    /** @type {FilterState} */
639	    const filterState = { search: '', repoId: '', sort: 'alpha' };
640	
641	    /**
642	     * Called whenever a toolbar control changes.  Applies the updated
643	     * filter/sort state to the cached project data without re-fetching.
644	     *
645	     * @param {FilterState} newState
646	     */
647	    const onFilterChange = (newState) => {
648	        Object.assign(filterState, newState);
649	        const filtered = applyFiltersAndSort(filterState);
650	        renderProjectGrid(listContainer, filtered);

651	    };
652	
653	    const toolbar = await buildFilterToolbar(filterState, onFilterChange);
654	    container.appendChild(toolbar);
655	
656	    // Insert list container after toolbar
657	    container.appendChild(listContainer);
658	
659	    // -----------------------------------------------------------------------
660	    // Create Project section
661	    // -----------------------------------------------------------------------
662	    const createSection = buildCreateProjectSection(() => {
663	        // Re-fetch all project data from the API and re-apply the current
664	        // filter/sort state so newly created projects appear immediately.
665	        renderProjectList(listContainer, filterState);
666	    });
667	    container.appendChild(createSection);
668	
669	    // -----------------------------------------------------------------------
670	    // Initial load
671	    // -----------------------------------------------------------------------
672	    await renderProjectList(listContainer, filterState);
673	}

